def length_of_longest_substring(s: str) -> int:
    n = len(s)
    best = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            if s[j] in seen:
                break
            seen.add(s[j])
            best = max(best, j - i + 1)
    return best


def main():
    s = input().strip()
    print(length_of_longest_substring(s))


if __name__ == "__main__":
    main()

def length_of_longest_substring(s: str) -> int:
    seen = set()
    l = 0
    best = 0
    for r, ch in enumerate(s):
        while ch in seen:
            seen.remove(s[l])
            l += 1
        seen.add(ch)
        best = max(best, r - l + 1)
    return best


def main():
    s = input().strip()
    print(length_of_longest_substring(s))


if __name__ == "__main__":
