def length_of_longest_substring(s: str) -> int:
    last = {}
    l = 0
    best = 0
    for r, ch in enumerate(s):
        if ch in last and last[ch] >= l:
            l = last[ch] + 1
        last[ch] = r
        best = max(best, r - l + 1)
    return best


def main():
    s = input().strip()
    print(length_of_longest_substring(s))


if __name__ == "__main__":
    main()
